 "content": "def transform(grid):
    # Split the canvas into tiles using the solid separator rows and columns.
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)
    candidates = [color for color in colors
                  if any(all(v == color for v in row) for row in grid)
                  and any(all(grid[r][c] == color for r in range(h)) for c in range(w))]
    sep = candidates[0] if candidates else max(colors, key=lambda c: sum(v == c for row in grid for v in row))

    row_bands, col_bands = [], []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))

    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # The most common color inside the tiles is their background.
    counts = {}
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    value = grid[r][c]
                    counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Mark tiles with exactly two non-background cells.
    output = []
    for r0, r1 in row_bands:
        result_row = []
        for c0, c1 in col_bands:
            non_background = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            result_row.append(1 if non_background == 2 else background)
        output.append(result_row)
    return output

